gl_arch=$(uname -m 2>/dev/null); case "$gl_arch" in x86_64) gl_want="/lib64/ld-linux-x86-64.so.2 /lib/ld-linux-x86-64.so.2";; aarch64) gl_want="/lib/ld-linux-aarch64.so.1";; *) gl_want=;; esac; for gl_p in $gl_want; do if [ -e "$gl_p" ]; then gl_want=; break; fi; done; if [ -n "$gl_want" ]; then echo "no glibc dynamic loader (${gl_want%% *} for $gl_arch)" >&2; exit 1; fi
